"""Function-calling schemas for adapters; only declared house operations are allowed."""
def field(kind,description,**more):return {'type':kind,'description':description,**more}
NUM=field('number','World position in meters; Y is up.')
ID=field('string','Unique furniture identifier',minLength=1,maxLength=64)
ASSET=field('string','Asset id returned by get_catalog.assets; no arbitrary URLs',minLength=1,maxLength=100)
COLOR=field('string','Furniture color',pattern='^#[0-9a-fA-F]{6}$')
ON=field('object','Place on a catalog-declared surface. x/z/yaw are local offsets; follows its parent. No arbitrary elevation.',properties={'id':ID,'surface':field('string','Surface id from the parent asset surfaces'),'x':NUM,'z':NUM,'yaw':NUM},required=['id','surface','x','z','yaw'],additionalProperties=False)
LAYOUT_ITEM={'on':ON,'id':ID,'asset_id':ASSET,'x':NUM,'z':NUM,'yaw':field('number','Yaw in radians'),'label':field('string','Display name',minLength=1,maxLength=40),'properties':field('object','Supported state fields'),'color':COLOR}
LAYOUT_OPERATION={'oneOf':[
 {'type':'object','properties':{**LAYOUT_ITEM,'op':{'const':'add'}},'required':['op','id','asset_id'],'additionalProperties':False},
 {'type':'object','properties':{**LAYOUT_ITEM,'op':{'const':'update'}},'required':['op','id'],'additionalProperties':False},
 {'type':'object','properties':{'op':{'const':'remove'},'id':ID},'required':['op','id'],'additionalProperties':False}]}
DEFS={
 'update_layout':('Batch add/update/remove selected catalog assets. dry_run defaults true: read-only report of all bounds/overlap errors and approximate interaction reachability warnings. false applies the whole batch once, only if can_apply; preserves room/character. Re-preview after revision or body changes.',{'operations':field('array','Ordered edits; final geometry is checked together (position swaps are supported).',minItems=1,maxItems=80,items=LAYOUT_OPERATION),'dry_run':field('boolean','Default true. false persists only a valid final layout.',default=True)},['operations']),
 'observe_home':('Read fresh character-perspective sight, body/support, nearby walls and incremental action feedback. Not the spectator camera; stale/no viewer is explicit.',{'since':field('integer','Last event cursor',minimum=0)},[]),
 'walk_to':('Walk along a validated route to a free room position. Asynchronous; inspect observe_home/job for completion.',{'x':NUM,'z':NUM},['x','z']),
 'cancel_action':('Cancel the matching current job. Seated/lying characters get up safely before completion.',{'job_id':field('string','Current job id')},['job_id']),
 'set_wallpaper':('Apply a catalog wallpaper to one wall or all four, preserving furniture, trim and navigation. Use plain to remove it; discover ids in get_catalog.wallpapers.',{'wall_id':field('string','Structural wall',enum=['back','front','left','right','all']),'wallpaper_id':field('string','Wallpaper id from the catalog')},['wall_id','wallpaper_id']),
 'update_room':('Change room dimensions/finishes. Width 4..12m, depth 4..10m, ceiling 2.4..4m. Wall fixtures follow walls; floor furniture stays put. Resizing rejects bounds/overlap and body obstruction. dry_run is read-only.',{'wall_color':COLOR,'trim_color':COLOR,'style':field('string','Wall detailing',enum=['classic','urban']),'width':field('number','Room width in metres',minimum=4,maximum=12),'depth':field('number','Room depth in metres',minimum=4,maximum=10),'height':field('number','Ceiling height',minimum=2.4,maximum=4),'dry_run':field('boolean','Preview without saving',default=False)},[]),
 'list_objects':('List placed objects by category/capability, their available actions, properties and current interaction.',{'category':field('string','Optional category id'),'capability':field('string','Optional action id')},[]),
 'interact':('Request an object action; inspect list_objects for availability. Pose actions are asynchronous: requested is not completed. leave gets up/exits or cancels an approach.',{'target_id':ID,'action':field('string','Declared action id',enum=['sit','sleep','read','leave','turn_on','turn_off','cover','uncover'])},['target_id','action']),
 'update_object':('Change a placed object label or supported properties. Lamps support on (boolean) and brightness (0..1). Supported beds have covered (boolean); other properties are rejected.',{'id':ID,'label':field('string','Display name',minLength=1,maxLength=40),'properties':field('object','Supported state fields')},['id']),
 'get_presets':('List the childroom and family-home templates. Applying resets furniture/room to the template, not a multi-room simulation.',{},[]),
 'apply_preset':('Switch the entire room atomically to a preset. Preserves character appearance; explicitly places her at the preset spawn. dry_run defaults true; false saves. Finish current interaction first.',{'preset_id':field('string','Preset id',enum=['childroom','family-home']),'dry_run':field('boolean','Preview first',default=True)},['preset_id']),
 'get_state':('Read the current persisted house state and revision.',{},[]),
 'get_catalog':('List supported assets, activities and explicit limitations.',{},[]),
 'set_light':('Change the room lighting.',{'preset':field('string','Lighting preset',enum=['day','evening','night'])},['preset']),
 'set_camera':('Choose room, frontal full body, face closeup, three-quarter, side, back or overhead view.',{'preset':field('string','Camera view',enum=['home','portrait','front','face','side','back','top'])},['preset']),
 'set_note':('Leave a note in the room.',{'text':field('string','Note',maxLength=240)},['text']),
 'set_activity':('idle and walk control the Canvas viewer. sit remains a legacy experimental pose, not supported by the wander viewer.',{'activity':field('string','Animation',enum=['idle','walk','sit'])},['activity']),
 'move_character':('Relocate to a free spot using the same character clearance as the Canvas viewer. This is not animated pathfinding.',{'x':dict(NUM,minimum=-5.28,maximum=5.28),'z':dict(NUM,minimum=-4.28,maximum=4.28),'yaw':field('number','Yaw angle in radians')},['x','z']),
 'place_furniture':('Add a catalog item; floor items require x/z. Surface props require on with catalog surface/local offsets; world pose is derived. Reject overlaps.',{'on':ON,'id':ID,'kind':field('string','Use the kind declared by the selected catalog asset, or a supported primitive kind'),'asset_id':ASSET,'x':NUM,'z':NUM,'yaw':field('number','Yaw in radians'),'color':COLOR,'label':field('string','Display name',minLength=1,maxLength=40),'properties':field('object','Supported state fields')},['id','kind']),
 'update_furniture':('Move, rotate or recolor an existing item.',{'on':ON,'id':ID,'asset_id':ASSET,'x':NUM,'z':NUM,'yaw':field('number','Yaw in radians'),'color':COLOR,'label':field('string','Display name',minLength=1,maxLength=40),'properties':field('object','Supported state fields')},['id']),
 'apply_layout':('Atomically replace furniture with an explicit layout. All items are validated together before saving.',{'objects':field('array','Complete desired furniture layout',maxItems=80,items={'type':'object','properties':{'on':ON,'id':ID,'kind':field('string','Furniture kind'),'asset_id':ASSET,'x':NUM,'z':NUM,'yaw':NUM,'color':COLOR,'label':field('string','Display name',minLength=1,maxLength=40),'properties':field('object','Supported state fields')},'required':['id','kind'],'additionalProperties':False})},['objects']),
 'remove_furniture':('Remove one item from the layout.',{'id':ID},['id']),
 'screenshot':('Request a PNG from the owner camera or character eyes; sleeping character view is dark. Requires a visible viewer; does not move the owner camera.',{'view':field('string','Viewpoint',enum=['spectator','character'])},[]),
}
def schemas():
 return [{'type':'function','function':{'name':name,'description':desc,'parameters':{'type':'object','properties':props,'required':required,'additionalProperties':False}}} for name,(desc,props,required) in DEFS.items()]
